// CLOSING TIME storyboard: shot list (metadata + sketch drawing for every shot).
'use strict';
const D = require('./draw');
const { W, H, rng, f, pts, poly, rect, frame, person, zombie, horde, sky, moon, skyline, fog, lampPost, car, shutter, aisle, storefront, aerial } = D;

const STYLE = 'Cinematic 3D animated film still, stylised cartoon characters with solid black skin, big round white eyes and simple bold clothes (match the character references), detailed realistic 3D environment, volumetric fog, moody cinematic lighting, anamorphic 2.39:1 frame, shallow depth of field, subtle film grain, no text, no logos';
const blur = (s, n = 'b8') => `<g filter="url(#${n})">${s}</g>`;
const bokeh = (seed, n, cols, y0 = 140, y1 = 940) => { const R = rng(seed); let s = ''; for (let i = 0; i < n; i++) s += `<circle cx="${f(R() * W)}" cy="${f(y0 + R() * (y1 - y0))}" r="${f(20 + R() * 60)}" fill="${cols[i % cols.length]}" opacity="${f(0.15 + R() * 0.3)}" filter="url(#b8)"/>`; return s; };
const lab = (id, size) => `${String(id).padStart(2, '0')}  ·  ${size}`;
const T = (x, y, txt, size, col, font = 'Figtree', extra = '') => `<text x="${x}" y="${y}" font-family="${font}" font-size="${size}" fill="${col}" ${extra}>${txt}</text>`;

// ---- recurring sets ----
function counter(y, tint = '#2b3138') { return rect(0, y, W, H - y, tint) + rect(0, y, W, 16, '#4a525c'); }
function windowsOut(o = {}) { // inside the store looking out through the front glass at night
  let s = sky('#05080d', '#17212e', 700) + skyline(520, 21, '#070a10', 0.03, 200) + rect(0, 520, W, 560, '#10141a');
  s += lampPost(o.lampX ?? 1250, 760, 330) + lampPost(260, 720, 300);
  s += car(520, 760, 0.8, '#3b4452') + car(1600, 800, 0.9, '#5a2a2a', true);
  s += o.outside || '';
  // glass reflections + frames
  s += `<rect width="${W}" height="${H}" fill="#9fd0ff" opacity="0.05"/>`;
  for (let i = 0; i <= 6; i++) s += rect((W / 6) * i - 10, 0, 20, H, '#262b31');
  s += rect(0, 200, W, 16, '#262b31');
  return s;
}
function stockroom(o = {}) { // red-lit back room with racking
  const R = rng(o.seed || 5); let s = rect(0, 0, W, H, o.bg || '#1a0b0b');
  for (let k = 0; k < 4; k++) { const x = 60 + k * 470; s += rect(x, 160, 360, 700, '#120707'); for (let l = 0; l < 4; l++) { s += rect(x, 300 + l * 160, 360, 10, '#3a1d1d'); for (let b = 0; b < 4; b++) s += rect(x + 10 + b * 88, 300 + l * 160 - 70 - R() * 30, 80, 70 + R() * 30, ['#4a2a1a', '#3a2418', '#553322'][b % 3]); } }
  s += rect(0, 860, W, 220, '#120808');
  s += `<ellipse cx="${o.lx ?? 960}" cy="180" rx="900" ry="500" fill="url(#poolRed)"/>`;
  return s;
}
function freezerDoor(x, y, w, h, o = {}) {
  let s = rect(x, y, w, h, '#a7b4bf') + rect(x + 16, y + 16, w - 32, h - 32, '#c4d0d9');
  s += rect(x + w - 70, y + h * 0.42, 34, 140, '#59626b', 'rx="10"');
  s += `<rect x="${x + 40}" y="${y + h - 120}" width="${w - 80}" height="80" fill="#e8f4ff" opacity="0.25" filter="url(#b8)"/>`;
  const lx = x + w + 30, ly = y + h * 0.4;
  s += rect(lx, ly, 120, 170, '#24282d', 'rx="10"') + rect(lx + 12, ly + 14, 96, 44, '#07120a', 'rx="4"');
  s += `<circle cx="${lx + 60}" cy="${ly + 110}" r="18" fill="${o.led || '#3dff6a'}" filter="url(#glow)"/>`;
  if (o.disp) s += T(lx + 60, ly + 46, o.disp, 26, o.dispCol || '#ff4a3a', 'JetBrains Mono', 'text-anchor="middle" font-weight="700"');
  return s;
}
function chalkboard(lines, o = {}) {
  let s = rect(0, 0, W, H, '#2b2018') + rect(250, 150, 1420, 780, '#6b4a2a', 'rx="16"') + rect(285, 185, 1350, 710, '#1e2b25');
  s += `<rect x="285" y="185" width="1350" height="710" fill="#ffffff" opacity="0.04" filter="url(#b20)"/>`;
  s += T(960, 285, "TODAY'S SPECIALS", 54, '#f2f2f2', 'Caveat', 'text-anchor="middle" opacity="0.25" text-decoration="line-through"');
  lines.forEach((l, i) => { s += T(380, 400 + i * 120, l.t, 84, l.c || '#f4f4f0', 'Caveat', `opacity="0.92" ${l.r ? `transform="rotate(${l.r} 380 ${400 + i * 120})"` : ''}`); });
  return s;
}
function monitorBank(feeds, o = {}) {
  let s = rect(0, 0, W, H, '#05080c');
  const cols = 4, mw = 400, mh = 225, gx = 120, gy = 190;
  feeds.forEach((fd, i) => {
    const x = gx + (i % cols) * (mw + 30), y = gy + Math.floor(i / cols) * (mh + 30);
    s += rect(x - 8, y - 8, mw + 16, mh + 16, '#1b1f24', 'rx="6"');
    s += `<svg x="${x}" y="${y}" width="${mw}" height="${mh}" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid slice"><g filter="url(#mono)">${fd}</g><rect width="${W}" height="${H}" fill="#7fb0ff" opacity="0.08"/></svg>`;
    s += T(x + 10, y + 24, `CAM ${i + 1}`, 18, '#d0f0d0', 'JetBrains Mono');
  });
  s += `<ellipse cx="960" cy="500" rx="900" ry="420" fill="url(#poolCool)" opacity="0.35"/>`;
  return s + (o.extra || '');
}

// ---- aerial city sets ----
const STORE = { x: -110, z: 300, w: 220, d: 130, h: 16 };
function storeBoxes(lit) {
  return [[STORE.x, STORE.z, STORE.w, STORE.d, STORE.h, '#3d434c', '#2a2f36', lit ? '#c8a35a' : '#30353c', 0]];
}
const clearStore = (x, z) => x > -260 && x < 210 && z > 140 && z < 520;
function crowdAround(n, seed, spread = 1) {
  return { n, fn: (R) => {
    const r = R();
    if (r < 0.42) return [STORE.x - 60 + R() * (STORE.w + 120), 170 + R() * 125]; // car park in front
    if (r < 0.62) return [STORE.x - 110 + R() * 50, 200 + R() * 300]; // left side
    if (r < 0.78) return [STORE.x + STORE.w + 40 + R() * 50, 200 + R() * 300]; // right side
    if (r < 0.9) { const st = Math.floor(R() * 8) - 4; return [st * 92 - 11 + R() * 20, 520 + R() * 1100 * spread]; } // streets pouring in from behind
    const bz = Math.floor(R() * 8) + 5; return [-700 + R() * 1400, bz * 92 + 81 - 10 + R() * 20]; // cross streets
  } };
}

// ---------- SHOTS ----------
const shots = [];
const add = (o) => shots.push(o);

// DAY 1
add({ id: 1, scene: 'Day 1 · Register 2', time: '0:00–0:06', size: 'ECU · insert', lens: '100mm macro', move: 'Slow push-in on the till screen; focus pulls from the price to the glowing time.',
  action: 'Till screen: ICE 10LB — $3.49. REG 2. 23:52.', audio: 'NARRATOR: "The last thing you ever sell is a bag of ice."  SFX: till beep, fridge hum. MUSIC: bland store muzak, slightly detuned.',
  prompt: 'Extreme close-up of a supermarket till display glowing green, showing an item line and a price, shallow depth of field, out-of-focus store lights behind, late night', draw: () => frame(rect(0, 0, W, H, '#11161c') + bokeh(2, 26, ['#ffffff', '#ffd27a', '#ff5a3a']) + `<g transform="rotate(-6 960 540)">${rect(420, 300, 1080, 480, '#20262c', 'rx="30"')}${rect(470, 350, 980, 380, '#0b2a12', 'rx="12"')}<rect x="470" y="350" width="980" height="380" fill="#38ff7a" opacity="0.08" filter="url(#b20)"/>${T(520, 470, 'ICE 10LB', 92, '#7dff9e', 'JetBrains Mono', 'filter="url(#glow)" font-weight="700"')}${T(1400, 470, '$3.49', 92, '#7dff9e', 'JetBrains Mono', 'text-anchor="end" filter="url(#glow)" font-weight="700"')}${T(520, 640, 'REG 2      23:52', 58, '#48c96a', 'JetBrains Mono', 'font-weight="700"')}</g>`, { label: lab(1, 'ECU'), sub: '100mm · push-in' }) });

