add({ id: 6, scene: 'Day 1 · The city', time: '0:42–0:48', size: 'AERIAL · establishing', lens: 'Drone, 24mm', move: 'High drone shot, slow forward glide and tilt down: the city in panic, one supermarket glowing in a dark car park, the first figures streaming toward its light.',
  action: 'Sirens pulse in the streets. Blocks go dark. The store is the brightest thing for a mile, and things are walking toward it.', audio: 'SFX: distant sirens, a helicopter, howls answering each other across blocks.',
  prompt: 'High aerial drone shot of a dark city at night, streets with flashing police lights, a single brightly lit supermarket in a car park at the centre, hundreds of small green-headed zombie figures streaming along the streets toward it, fires in the distance, volumetric haze', draw: () => { const a = aerial({ h: 480, pitch: 55, f: 1250, seed: 31, lit: 0.07, tall: 35, clear: clearStore, boxes: storeBoxes(true), quads: [[[[STORE.x - 70, 0.2, 160], [STORE.x + STORE.w + 70, 0.2, 160], [STORE.x + STORE.w + 70, 0.2, STORE.z], [STORE.x - 70, 0.2, STORE.z]], '#2b3036']], crowd: [{ n: 1600, size: 1.1, fn: (R) => { let x, z; if (R() < 0.6) { const st = Math.floor(R() * 10) - 5; x = st * 92 - 11 + R() * 18; z = 60 + R() * 900; } else { const bz = Math.floor(R() * 9); x = -900 + R() * 1800; z = bz * 92 + 71 + R() * 18; } if (x > -180 && x < 180 && z > 290 && z < 440) x += x < 0 ? -200 : 200; return [x, z]; } }], fires: [[700, 1500, 30], [-900, 1900, 40]], extra: [{ x: 0, z: 220, draw: (p, k) => `<ellipse cx="${p[0]}" cy="${p[1]}" rx="${k * 200}" ry="${k * 80}" fill="url(#pool)"/>`, bias: -999 }, ...[[-200, 60], [180, -40], [-380, -200]].map(([x, z], i) => ({ x, z, draw: (p, k) => `<circle cx="${p[0]}" cy="${p[1]}" r="${Math.max(6, k * 14)}" fill="${i % 2 ? '#3a6bff' : '#ff2a2a'}" filter="url(#glow)" opacity="0.9"/>` }))] }); return frame(rect(0, 0, W, H, '#070a0f') + a.svg + `<rect width="${W}" height="500" fill="#1a2433" opacity="0.5" filter="url(#b40)"/>`, { label: lab(6, 'AERIAL'), sub: 'drone · glide + tilt' }); } });

