add({ id: 18, scene: 'Day 8 · Outside the shutter', time: '3:55–4:15', size: 'Long-lens wide', lens: '200mm telephoto', move: 'Locked off; heat-haze compression makes the horde behind look right on top of the kids.',
  action: 'Four teenagers pressed against the shutter, knocking a pattern. Down the street, the horde turns their way like one animal.', audio: 'MAYA (O.S.): "Hello? Please. We\'ve been on the roof next door for a week..."  RICO (O.S.): "Maya. They heard us."',
  prompt: 'Telephoto compressed shot at night of four frightened teenagers (REF Maya, Zoe, Theo, Rico) pressed against a closed supermarket steel shutter, behind them far down the street a huge zombie horde turning toward them, foggy, sodium light', draw: () => frame(sky('#05080d', '#1a2433', 500) + skyline(470, 18, '#080b11', 0.02, 260) + rect(0, 460, W, 620, '#151a20') + horde({ n: 220, x0: 0, x1: W, yTop: 470, yBot: 640, sTop: 0.08, sBot: 0.22, seed: 18, dir: 1 }) + fog(380, 400, 1) + shutter(0, 140, 260, 900) + shutter(1660, 140, 260, 900) + rect(260, 860, 1400, 220, '#1d232b') + person({ who: 'maya', x: 640, y: 1080, s: 1.35, mood: 'scared', look: 1, arms: 'reach', dir: 1 }) + person({ who: 'zoe', x: 900, y: 1080, s: 1.3, mood: 'angry', look: -1 }) + person({ who: 'theo', x: 1160, y: 1080, s: 1.35, mood: 'scared', look: -1 }) + person({ who: 'rico', x: 1420, y: 1080, s: 1.45, mood: 'scared', look: -1, back: false }) + lampPost(60, 1000, 600), { label: lab(18, 'LONG LENS'), sub: '200mm · compressed' }) });

add({ id: 19, scene: 'Day 8 · The gap', time: '4:15–4:35', size: 'Ground level · wide', lens: '16mm, lens on the floor', move: 'Camera on the floor inside. Bodies slide under the shutter straight at the lens, slow motion as the hand grabs Zoe\'s ankle.',
  action: 'Sami holds the shutter two feet up. Theo, Maya and Rico roll in. Zoe last: a green hand grabs her ankle, she kicks free, her arm scrapes the steel edge.', audio: 'MUSIC: heartbeat. SFX: bodies on tile, the shutter slams. ZOE: "Who are you?"  SAMI: "...Can I help you find anything?"',
  prompt: 'Floor-level wide shot inside a supermarket at night, a steel shutter raised two feet, teenagers sliding underneath toward camera, a blonde girl in a denim jacket (REF Zoe) half through with a green zombie hand grabbing her ankle from outside, slow motion', draw: () => frame(rect(0, 0, W, H, '#0e1218') + shutter(0, 140, W, 560) + rect(0, 700, W, 120, '#05070a') + horde({ n: 14, x0: 0, x1: W, yTop: 820, yBot: 830, sTop: 0.42, sBot: 0.42, seed: 19, pow: 1, dir: 1 }) + rect(0, 700, W, 16, '#6a7078') + rect(0, 820, W, 260, '#2b333c') + `<g transform="translate(1080,880) rotate(-80)">${person({ who: 'zoe', x: 0, y: 0, s: 1.1, mood: 'scared', look: 1, arms: 'reach', dir: 1 })}</g>` + `<path d="M1380,830 l120,-30 l20,24 l-110,40Z" fill="#4f7d2c"/>` + `<g transform="translate(560,1000) rotate(-10)">${person({ who: 'theo', x: 0, y: 0, s: 0.9, pose: 'crouch', mood: 'scared' })}</g>` + person({ who: 'sami', x: 260, y: 1090, s: 1.5, mood: 'scared', arms: 'up', look: 1 }), { label: lab(19, 'GROUND LEVEL'), sub: '16mm · slow-mo' }) });

add({ id: 20, scene: 'Day 8 · Stockroom', time: '4:35–5:00', size: 'Medium group shot', lens: '35mm', move: 'Slow arc (half-orbit) around the group by candlelight.',
  action: 'Five people in candlelight. Maya takes the peroxide off Zoe and cleans the cut with water and soap. Rico smiles. Theo clutches his speaker: "It\'s OFF!"', audio: 'MAYA: "Not that. ...Clean water, soap, and a lot of it."  ZOE: "Is she always like this?"  THEO: "It\'s off!"',
  prompt: 'Warm candlelit medium group shot in a supermarket stockroom, five teenagers (REF Sami, Maya, Zoe, Theo, Rico) sitting on boxes, the girl in a yellow hoodie cleaning a scrape on the blonde girl\'s arm with bottled water, a boy hugging a small speaker', draw: () => frame(stockroom({ bg: '#1a1208', seed: 20 }) + `<rect width="${W}" height="${H}" fill="#ff9a2a" opacity="0.12"/><ellipse cx="960" cy="760" rx="800" ry="420" fill="url(#pool)"/>` + person({ who: 'rico', x: 330, y: 1020, s: 1.25, pose: 'sit', mood: 'smile', look: 1, dir: 1 }) + person({ who: 'zoe', x: 760, y: 1000, s: 1.2, pose: 'sit', mood: 'angry', look: 1, dir: 1, arms: 'hold' }) + person({ who: 'maya', x: 1020, y: 1020, s: 1.2, pose: 'crouch', mood: 'calm', look: -1 }) + person({ who: 'theo', x: 1360, y: 1000, s: 1.2, pose: 'sit', mood: 'scared', look: -1, dir: -1, arms: 'hold' }) + rect(1320, 760, 80, 50, '#111', 'rx="10"') + person({ who: 'sami', x: 1680, y: 1040, s: 1.3, mood: 'smile', look: -1 }) + `<circle cx="960" cy="960" r="10" fill="#fff1b0" filter="url(#glow)"/>` + rect(950, 965, 20, 50, '#eee'), { label: lab(20, 'GROUP'), sub: '35mm · half-orbit' }) });

