add({ id: 21, scene: 'Day 9 · Blackout', time: '5:00–5:15', size: 'ECU insert', lens: '100mm macro', move: 'Static, the digits tick. Shallow focus; the freezer handle soft behind.',
  action: 'The lights die. The freezer lock switches to battery: 48:00:00 → 47:59:59.', audio: 'SFX: every hum dies at once, then one tiny digital beep per second. NARRATOR: "Forty-eight hours. Then the door opens..."',
  prompt: 'Extreme close-up of a small red LCD display on an electronic freezer lock reading a countdown, dark stockroom, frost on the steel around it, shallow depth of field', draw: () => frame(rect(0, 0, W, H, '#07090c') + rect(380, 260, 1160, 560, '#1e2227', 'rx="40"') + rect(460, 340, 1000, 300, '#140303', 'rx="16"') + `<rect x="460" y="340" width="1000" height="300" fill="#ff2a1a" opacity="0.12" filter="url(#b20)"/>` + T(960, 420, 'BATTERY BACKUP', 46, '#ff6a5a', 'JetBrains Mono', 'text-anchor="middle" font-weight="700"') + T(960, 580, '47:59:59', 150, '#ff3b2e', 'JetBrains Mono', 'text-anchor="middle" font-weight="700" filter="url(#glow)"') + `<circle cx="960" cy="720" r="26" fill="#3dff6a" filter="url(#glow)"/>`, { label: lab(21, 'ECU'), sub: '100mm · static' }) });

add({ id: 22, scene: 'Day 9 · Stockroom', time: '5:15–5:30', size: 'Low wide', lens: '21mm', move: 'Low dolly toward the running generator; torch beams cut through the exhaust haze building in the room.',
  action: 'A petrol generator roars inside the closed stockroom, cable running to the freezer lock. Haze hangs in the torch beams.', audio: 'RICO: "Outside\'s not an option." NARRATOR: "It\'s the most reasonable mistake you\'ve ever made."  SFX: muffled generator drone.',
  prompt: 'Low-angle wide shot of a portable petrol generator running inside a closed dark supermarket stockroom, grey exhaust haze hanging in the beams of flashlights, a cable running to a freezer door, teenagers in silhouette', draw: () => frame(stockroom({ bg: '#0c0c0e', seed: 22 }) + `<rect width="${W}" height="${H}" fill="#000" opacity="0.4"/>` + freezerDoor(1200, 200, 420, 640) + `<path d="M1000,940 C1100,900 1150,800 1340,700" stroke="#111" stroke-width="10" fill="none"/>` + `<g transform="translate(760,980)">${rect(-200, -220, 400, 220, '#e0a81a', 'rx="16"')}${rect(-170, -190, 340, 120, '#2a2a2a', 'rx="10"')}<circle cx="150" cy="-240" r="18" fill="#444"/></g>` + `<polygon points="200,200 360,180 1100,700 980,780" fill="#fff6d8" opacity="0.12"/><polygon points="1760,240 1880,280 1000,760 900,700" fill="#fff6d8" opacity="0.1"/>` + `<g filter="url(#b40)" opacity="0.55"><ellipse cx="760" cy="640" rx="500" ry="180" fill="#8a8f96"/><ellipse cx="1100" cy="460" rx="700" ry="160" fill="#6a6f76"/></g>` + person({ who: 'rico', x: 300, y: 1060, s: 1.4, back: true }) + person({ who: 'zoe', x: 1700, y: 1080, s: 1.4, back: true }), { label: lab(22, 'LOW WIDE'), sub: '21mm · low dolly' }) });

add({ id: 23, scene: 'Day 10 · The air', time: '5:30–6:05', size: 'Medium · handheld', lens: '35mm, handheld', move: 'Handheld, unsteady, slightly out of focus (we feel the CO). Snaps sharp when Theo breathes.',
  action: 'Theo collapses. Sami drags him to the dock door and holds his face to the crack of grey morning light under it.', audio: 'MAYA: "It\'s not the food. It\'s the air." NARRATOR: "Carbon monoxide. No colour. No smell..." [NO WORDS 5s: breathing]  THEO: "...Did I miss anything?"',
  prompt: 'Handheld medium shot on a stockroom floor, a teenage boy in a red T-shirt (REF Sami) holding his unconscious curly-haired friend (REF Theo) so his face is at the narrow strip of daylight under a roll-up loading dock door, dust in the light beam', draw: () => frame(rect(0, 0, W, H, '#0d1014') + shutter(0, 140, W, 700, 0.8) + `<rect x="0" y="836" width="${W}" height="10" fill="#e8f2ff" filter="url(#glow)"/><polygon points="0,846 ${W},846 ${W},1080 0,1080" fill="#9fc0e0" opacity="0.18"/>` + rect(0, 846, W, 240, '#14181d', 'opacity="0.8"') + `<g transform="translate(1560,870) rotate(-90)">${person({ who: 'theo', x: 0, y: 0, s: 1.0, mood: 'closed', arms: 'stand' })}</g>` + person({ who: 'sami', x: 820, y: 1060, s: 1.5, pose: 'crouch', mood: 'scared', look: 1, arms: 'hold' }), { label: lab(23, 'HANDHELD'), sub: '35mm · soft → sharp' }) });

add({ id: 24, scene: 'Day 11 · The countdown', time: '6:05–6:15', size: 'Wide · symmetrical', lens: '28mm', move: 'Locked-off and dead centre, then a very slow push as the display hits zero.',
  action: 'All five in a line with mop-handle spears, backs to us, facing the freezer door. The display: 00:00:03… 2… 1…', audio: 'SFX: beep… beep… beep… CLICK. Silence. A long, slow creak.',
  prompt: 'Symmetrical wide shot from behind five teenagers in a line (REF Sami, Maya, Zoe, Theo, Rico) holding makeshift spears made from mop handles, facing a steel walk-in freezer door in a red-lit stockroom, a red countdown display beside the door reading one second', draw: () => frame(stockroom({ seed: 24 }) + freezerDoor(720, 180, 480, 660, { disp: '00:00:01', led: '#ff3b2e' }) + ['zoe', 'maya', 'sami', 'theo', 'rico'].map((w, i) => person({ who: w, x: 360 + i * 300, y: 1090, s: 1.35, back: true, arms: 'hold' }) + `<line x1="${330 + i * 300}" y1="1050" x2="${400 + i * 300}" y2="${560}" stroke="#a8875a" stroke-width="12"/><polygon points="${pts([[392 + i * 300, 560], [408 + i * 300, 560], [400 + i * 300, 500]])}" fill="#ddd"/>`).join(''), { label: lab(24, 'WIDE · SYM'), sub: '28mm · locked → push' }) });

add({ id: 25, scene: 'Day 11 · The freezer opens', time: '6:15–6:25', size: 'Medium wide · backlit', lens: '40mm', move: 'Static as the mist rolls toward the lens; the figure walks out of the white into silhouette.',
  action: 'The door swings open. Cold white light and mist pour across the floor. Mr. Davis walks out of it, frosted, eyes glowing, and howls.', audio: '[NO WORDS 6s] Then a howl. MUSIC: a single sub hit.',
  prompt: 'Medium wide shot of an open walk-in freezer doorway blazing with cold white light, thick mist pouring out across a dark stockroom floor, the silhouette of a zombie store manager in a tie (REF Davis) with glowing yellow eyes stepping out of the mist', draw: () => frame(stockroom({ bg: '#07090c', seed: 25 }) + `<rect width="${W}" height="${H}" fill="#000" opacity="0.5"/>` + rect(700, 180, 520, 680, '#e8f6ff') + `<rect x="600" y="100" width="720" height="860" fill="#bfe3ff" opacity="0.6" filter="url(#b40)"/>` + `<g filter="url(#b20)" opacity="0.8"><ellipse cx="960" cy="900" rx="900" ry="160" fill="#dceeff"/><ellipse cx="700" cy="980" rx="600" ry="100" fill="#cfe6ff"/></g>` + `<g filter="url(#b3)">${zombie({ x: 960, y: 880, s: 1.4, dir: 1, zshirt: '#0d0f12' })}</g>` + `<g filter="url(#glow)"><circle cx="${960 - 0.16 * 560 * 0.4}" cy="${880 - 560 + 0.16 * 560}" r="12" fill="#ffe680"/><circle cx="${960 + 0.16 * 560 * 0.4}" cy="${880 - 560 + 0.16 * 560}" r="12" fill="#ffe680"/></g>`, { label: lab(25, 'BACKLIT'), sub: '40mm · static' }) });

add({ id: 26, scene: 'Day 11 · The bite', time: '6:25–6:40', size: 'Two-shot CU', lens: '85mm', move: 'Slow push from the hand up to Rico\'s calm face.',
  action: 'Rico on the floor holding his hand: a bite across the back of it. Maya kneels, shaking. He smiles too calmly.', audio: 'MAYA: "Let me see it." RICO: "It\'s a hand. Hands are slow, right?" NARRATOR: "Hours, not seconds. That\'s the good news..."',
  prompt: 'Close two-shot on a stockroom floor, a teenage boy in a backwards cap and green flannel shirt (REF Rico) calmly looking at a bite on the back of his hand, a girl in a yellow hoodie (REF Maya) kneeling in front of him in tears, dim red emergency light', draw: () => frame(stockroom({ seed: 26 }) + `<rect width="${W}" height="${H}" fill="#000" opacity="0.3"/>` + person({ who: 'rico', x: 1220, y: 1500, s: 2.6, mood: 'smile', look: -0.6 }) + person({ who: 'maya', x: 520, y: 1520, s: 2.4, mood: 'sad', look: 1, back: false }) + `<g transform="translate(900,820)"><ellipse rx="90" ry="64" fill="#141414"/><path d="M-40,-10 q40,-30 80,0 M-40,14 q40,30 80,0" stroke="#7a1a1a" stroke-width="10" fill="none"/><path d="M40,0 q60,-20 120,20 M30,20 q50,40 90,90" stroke="#5aa03a" stroke-width="5" fill="none" opacity="0.8"/></g>`, { label: lab(26, 'TWO-SHOT'), sub: '85mm · push' }) });

// DAYS 12-13
add({ id: 27, scene: 'Day 12 · The recording', time: '6:40–7:00', size: 'Insert · screen', lens: '50mm', move: 'Push into the monitor until the scan lines fill the frame; the footage freezes.',
  action: 'Grainy CCTV, DAY 2 04:17: a small blue car pulls in; a woman runs toward the store and out of frame. The car door stays open. Live feed: the same car, a pink scarf caught in the door.', audio: 'NARRATOR: "She came. She said she would, and she came..." · "She runs out of frame. And she never runs back into it."',
  prompt: 'Grainy black-and-white security camera footage of a supermarket car park at night, a small car with its driver door left open and a scarf caught in it, a woman running out of frame, timestamp overlay', draw: () => frame(`<g filter="url(#mono)">${rect(0, 0, W, H, '#2a2a2a') + rect(0, 500, W, 580, '#3a3a3a') + car(800, 860, 1.3, '#6a8ab0') + `<path d="M920,720 l50,80 l-40,70" stroke="#d07aa0" stroke-width="18" fill="none"/>` + person({ who: 'mum', x: 1560, y: 860, s: 0.9, pose: 'run', dir: 1, back: true })}</g>` + Array.from({ length: 60 }, (_, i) => `<line x1="0" y1="${140 + i * 14}" x2="${W}" y2="${140 + i * 14}" stroke="#000" stroke-opacity="0.25" stroke-width="3"/>`).join('') + T(80, 220, 'CAM 1   DAY 2   04:17:32', 44, '#e8ffe8', 'JetBrains Mono', 'font-weight="700"') + `<circle cx="1780" cy="205" r="16" fill="#ff3b2e"/>`, { label: lab(27, 'INSERT'), sub: '50mm · push into screen', tint: '#9fc0ff', blend: 'multiply' }) });

add({ id: 28, scene: 'Day 12 · Grief', time: '7:00–7:10', size: 'Wide · low key', lens: '135mm', move: 'Long lens from the far end of an aisle; static. Let it sit.',
  action: 'Sami slides down the wall. Maya sits next to him and doesn\'t say anything. She just stays.', audio: '[NO WORDS] MUSIC: Sami\'s piano theme, one hand only.',
  prompt: 'Long-lens wide shot down a dark supermarket aisle, at the far end two small figures sitting on the floor against the wall, a boy in a red T-shirt (REF Sami) and a girl in a yellow hoodie (REF Maya), a single shaft of grey dawn light', draw: () => { const a = aisle({ light: 'dawn', seed: 28, empty: 0.55 }); return frame(a.svg + `<polygon points="1100,140 1260,140 1040,800 900,800" fill="#dfeaff" opacity="0.08"/>` + person({ who: 'sami', x: 920, y: 600, s: 0.32, pose: 'sit', mood: 'sad', dir: 1 }) + person({ who: 'maya', x: 1000, y: 600, s: 0.3, pose: 'sit', mood: 'sad', dir: -1 }), { label: lab(28, 'WIDE'), sub: '135mm · static' }); } });

add({ id: 29, scene: 'Day 13 · The plan', time: '7:10–7:40', size: 'Overhead', lens: '28mm, top shot', move: 'Top-down, slowly rotating as hands point at the map.',
  action: 'Around a cereal-box map of the city: a crackling radio, a torch, five pairs of hands. Rico\'s hand is wrapped; green veins up his arm.', audio: 'RADIO: "...Harlow Stadium roof. Helicopters leave at noon, day fourteen." ZOE: "Three miles..." RICO: "They go where the noise is. So we give them noise."',
  prompt: 'Top-down overhead shot of five teenagers around a stockroom table, a hand-drawn city map on a flattened cereal box, a battery radio, a flashlight, hands pointing at a stadium on the map, one boy\'s bandaged hand with green veins', draw: () => { let s = rect(0, 0, W, H, '#0e0f12') + rect(460, 220, 1000, 660, '#5a3d24', 'rx="20"') + `<g transform="rotate(-4 960 550)">${rect(620, 300, 680, 480, '#e8dcc0')}${rect(620, 300, 680, 90, '#d63a3a')}<path d="M660,700 L900,520 L1120,610 L1250,430" stroke="#333" stroke-width="10" stroke-dasharray="20 14" fill="none"/><circle cx="1250" cy="430" r="40" fill="none" stroke="#d63a3a" stroke-width="10"/>${T(1250, 360, 'STADIUM', 34, '#222', 'Caveat', 'text-anchor="middle"')}${T(660, 760, 'US', 34, '#222', 'Caveat')}</g>` + rect(1320, 640, 140, 90, '#2a2a2a', 'rx="10"') + `<ellipse cx="960" cy="540" rx="560" ry="400" fill="url(#pool)"/>`;
    const heads = [['sami', 960, 1000], ['maya', 380, 640], ['zoe', 960, 120], ['theo', 1560, 360], ['rico', 1560, 800]];
    heads.forEach(([w, x, y]) => { const L = D.LOOKS[w]; s += `<circle cx="${x}" cy="${y}" r="130" fill="${L.shirt}"/><circle cx="${x}" cy="${y}" r="80" fill="#141414"/><circle cx="${x}" cy="${y}" r="74" fill="${{ sami: '#5a3a22', maya: '#6b4226', zoe: '#f2c94c', theo: '#2b1d14', rico: '#2c2c30' }[w]}"/>`; });
    s += `<path d="M1500,760 L1260,600" stroke="#141414" stroke-width="44" stroke-linecap="round"/><path d="M1460,730 L1300,625" stroke="#5aa03a" stroke-width="5" opacity="0.8"/><rect x="1240" y="580" width="60" height="40" fill="#eee" transform="rotate(30 1270 600)"/>`;
    return frame(s, { label: lab(29, 'OVERHEAD'), sub: 'top shot · rotate' }); } });

